import { one, q, type Db } from "../db";
import type { Policies } from "../booking/availability";

type Res = { id: string; business_id: string; customer_id: string; customer_email: string | null; starts_at: Date; status: string };
export type JobKind = "confirmation" | "reminder" | "cancellation" | "reschedule";

async function insertJob(db: Db, r: Res, kind: JobKind, dedupeKey: string, runAt: Date = new Date()) {
  // ON CONFLICT DO NOTHING: retrying the surrounding operation can never queue the same message twice.
  await q(
    `INSERT INTO notification_jobs (business_id, reservation_id, kind, recipient, dedupe_key, run_at)
     VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (dedupe_key) DO NOTHING`,
    [r.business_id, r.id, kind, r.customer_email, dedupeKey, runAt], db,
  );
}

function reminderTime(p: Policies, r: Res): Date | null {
  if (p.reminder_hours_before <= 0) return null;
  const at = new Date(r.starts_at.getTime() - p.reminder_hours_before * 3600_000);
  return at.getTime() > Date.now() + 60_000 ? at : null; // booked inside the reminder window: no reminder
}

/**
 * Queue customer messages for a reservation event. Nothing is queued when the business turned
 * email off, the customer gave no email address, or the customer declined booking messages.
 */
export async function enqueueForReservation(db: Db, p: Policies, r: Res, kind: Exclude<JobKind, "reminder">, consent?: boolean) {
  if (!p.email_notifications || !r.customer_email) return;
  const ok = consent ?? (await one<{ notify_consent: boolean }>("SELECT notify_consent FROM customers WHERE id = $1", [r.customer_id], db))?.notify_consent;
  if (!ok) return;
  if (kind === "confirmation") {
    await insertJob(db, r, "confirmation", `confirmation:${r.id}`);
    const at = reminderTime(p, r);
    if (at) await insertJob(db, r, "reminder", `reminder:${r.id}`, at);
  } else if (kind === "cancellation") {
    await insertJob(db, r, "cancellation", `cancellation:${r.id}`);
  } else {
    await insertJob(db, r, "reschedule", `reschedule:${r.id}:${r.starts_at.toISOString()}`);
  }
}

export async function cancelQueuedReminders(db: Db, reservationId: string) {
  await q("UPDATE notification_jobs SET status = 'cancelled', updated_at = now() WHERE reservation_id = $1 AND kind = 'reminder' AND status = 'queued'", [reservationId], db);
}

export async function moveReminder(db: Db, p: Policies, r: Res) {
  const at = reminderTime(p, r);
  if (!at) return cancelQueuedReminders(db, r.id);
  const moved = await q("UPDATE notification_jobs SET run_at = $2, updated_at = now() WHERE dedupe_key = $1 AND status = 'queued' RETURNING id", [`reminder:${r.id}`, at], db);
  if (moved.length === 0 && p.email_notifications && r.customer_email) await insertJob(db, r, "reminder", `reminder:${r.id}`, at);
}
