import Link from "next/link";
import { DateTime } from "luxon";
import { getDayAvailability, loadContext } from "@/lib/booking/availability";
import { listReservations } from "@/lib/booking/search";
import { pageMember } from "@/lib/page";
import { isIsoDate, minutesToLabel, todayIn } from "@/lib/time";
import { Card } from "@/components/ui";

export const metadata = { title: "Calendar" };

const BAR: Record<string, string> = {
  confirmed: "bg-brand text-white", pending: "bg-amber-soft text-amber ring-1 ring-amber/40", checked_in: "bg-mint text-white", completed: "bg-line text-ink-soft",
};

export default async function CalendarPage({ params, searchParams }: { params: Promise<{ slug: string }>; searchParams: Promise<{ date?: string }> }) {
  const { slug } = await params;
  const { business } = await pageMember(slug);
  const tz = business.timezone;
  const today = todayIn(tz);
  const sp = await searchParams;
  const date = sp.date && isIsoDate(sp.date) ? sp.date : today;
  const day = DateTime.fromISO(date, { zone: tz });
  const ctx = await loadContext(business.id);
  const [{ rows }, avail] = await Promise.all([
    listReservations(business.id, tz, { from: date, to: date, limit: 200 }),
    getDayAvailability(business.id, { date, partySize: 1, staff: true, now: new Date(0) }, undefined, ctx),
  ]);
  const live = rows.filter((r) => !["cancelled", "no_show"].includes(r.status));
  const hours = ctx.hours.filter((h) => h.weekday === day.weekday);
  const winStart = hours.length ? Math.floor(Math.min(...hours.map((h) => h.open_min)) / 60) * 60 : 9 * 60;
  const winEnd = hours.length ? Math.ceil(Math.max(...hours.map((h) => h.close_min)) / 60) * 60 : 21 * 60;
  const span = winEnd - winStart;
  const resources = ctx.resources.filter((r) => r.active || live.some((x) => x.resource_id === r.id));
  const ticks = Array.from({ length: span / 60 + 1 }, (_, i) => winStart + i * 60);
  const total = resources.filter((r) => r.active).length;
  const pos = (d: Date) => { const l = DateTime.fromJSDate(d, { zone: tz }); return ((l.hour * 60 + l.minute - winStart) / span) * 100; };
  const link = (d: DateTime) => `/app/${slug}/calendar?date=${d.toISODate()}`;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-3xl font-extrabold">Calendar</h1>
          <p className="text-ink-soft">{day.toFormat("cccc d LLLL yyyy")}{date === today ? " (today)" : ""}</p>
        </div>
        <div className="flex items-center gap-2">
          <Link href={link(day.minus({ days: 1 }))} className="inline-flex min-h-11 items-center rounded-xl px-4 font-semibold ring-1 ring-line hover:bg-white">Previous day</Link>
          <Link href={`/app/${slug}/calendar`} className="inline-flex min-h-11 items-center rounded-xl px-4 font-semibold ring-1 ring-line hover:bg-white">Today</Link>
          <Link href={link(day.plus({ days: 1 }))} className="inline-flex min-h-11 items-center rounded-xl px-4 font-semibold ring-1 ring-line hover:bg-white">Next day</Link>
        </div>
      </div>
      <form method="get" className="flex items-end gap-2">
        <label className="block"><span className="mb-1 block text-sm font-semibold text-ink-soft">Jump to date</span><input type="date" name="date" defaultValue={date} className="min-h-11 rounded-xl border border-line bg-white px-3" /></label>
        <button className="min-h-11 rounded-xl bg-ink px-4 font-semibold text-white">Go</button>
      </form>

      {!avail.open ? (
        <Card className="px-6 py-10 text-center"><p className="font-display text-xl font-bold">{avail.closedReason ?? "Closed"}</p>{live.length > 0 && <p className="mt-1 text-rose">{live.length} existing {live.length === 1 ? "reservation falls" : "reservations fall"} on this day.</p>}</Card>
      ) : (
        <>
          <section>
            <h2 className="mb-2 text-lg font-bold">Free {business.type === "restaurant" ? "tables" : "places"} by start time</h2>
            <div className="flex flex-wrap gap-1.5">
              {avail.slots.map((s) => (
                <div key={s.start} className={`w-[4.2rem] rounded-lg px-1 py-1.5 text-center ring-1 ${s.free === 0 ? "bg-rose-soft ring-rose/30" : s.free < total && s.free <= Math.max(1, total * 0.25) ? "bg-amber-soft ring-amber/30" : "bg-white ring-line"}`}>
                  <p className="text-[13px] text-ink-soft tabular">{s.time}</p>
                  <p className="font-display text-lg leading-tight font-bold tabular">{s.free}<span className="text-[13px] font-medium text-muted">/{total}</span></p>
                </div>
              ))}
            </div>
          </section>

          <section>
            <h2 className="mb-2 text-lg font-bold">Timeline <span className="font-sans text-base font-medium text-muted">{live.length} {live.length === 1 ? "reservation" : "reservations"}, {live.reduce((n, r) => n + r.party_size, 0)} guests</span></h2>
            <Card className="overflow-x-auto">
              <div className="min-w-[640px] p-3 pr-8">
                <div className="relative ml-28 h-6 text-[13px] text-muted tabular">
                  {ticks.map((t) => <span key={t} className="absolute -translate-x-1/2" style={{ left: `${((t - winStart) / span) * 100}%` }}>{minutesToLabel(t)}</span>)}
                </div>
                {resources.map((res) => (
                  <div key={res.id} className="flex items-center border-t border-line">
                    <div className="w-28 shrink-0 py-2 pr-2">
                      <p className={`truncate text-[15px] font-semibold ${res.active ? "" : "text-muted line-through"}`}>{res.name}</p>
                      <p className="text-[13px] text-muted">seats {res.capacity}</p>
                    </div>
                    <div className="relative h-12 flex-1" style={{ backgroundImage: "linear-gradient(to right, var(--color-line) 1px, transparent 1px)", backgroundSize: `${(60 / span) * 100}% 100%` }}>
                      {live.filter((r) => r.resource_id === res.id).map((r) => (
                        <Link key={r.id} href={`/app/${slug}/reservations/${r.id}`} title={`${r.customer_name}, ${r.party_size} guests, ${r.reference}`}
                          className={`absolute top-1.5 bottom-1.5 overflow-hidden rounded-lg px-2 text-[13px] leading-9 font-semibold whitespace-nowrap ${BAR[r.status] ?? "bg-line"}`}
                          style={{ left: `${Math.max(0, pos(r.starts_at))}%`, width: `${Math.max(3, pos(r.ends_at) - pos(r.starts_at))}%` }}>
                          {r.customer_name} ({r.party_size})
                        </Link>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </Card>
          </section>
        </>
      )}
    </div>
  );
}
